/* C API of the Rust port of `fanger.c`, generated by rust-anything. */
#ifndef FANGER_RS_H
#define FANGER_RS_H

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>
#include <sys/types.h>

double FangerPMV(int which, double at, double rt, double rh, double vel, double act, double clo, double work);
double StandardEffectiveTemp(int which, double outbaro, double at, double rt, double rh, double vel, double act, double clo, double work);

/* The same functions under `rust_anything_` names, for shadow runs. */
double rust_anything_FangerPMV(int which, double at, double rt, double rh, double vel, double act, double clo, double work);
double rust_anything_StandardEffectiveTemp(int which, double outbaro, double at, double rt, double rh, double vel, double act, double clo, double work);

#endif /* FANGER_RS_H */
